# ---------------- write & verify ----------------
def main():
    assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
    OUT.mkdir(parents=True, exist_ok=True)
    total = 0
    for cid in IDS:
        d = P[cid]
        obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": d["trigger"]}
        data = json.dumps(obj, ensure_ascii=False, indent=1).encode("utf-8")
        (OUT / f"{cid}.json").write_bytes(data)
        total += len(data)
    # read-back verification (own outputs only)
    cnt = 0; trig = {"changed_main":0,"reserve_used":0,"disputed":0}
    for cid in IDS:
        o = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
        assert o["case_id"] == cid and o["prediction_text"] and o["basis"] and 0 <= o["confidence"] <= 1
        assert set(o["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
        first = o["basis"].splitlines()[0]
        assert first.startswith("tradition:"), (cid, first)
        assert "systems_used" in o["basis"]
        for k in trig: trig[k] += int(bool(o["trigger"][k]))
        cnt += 1
    print(json.dumps({"written": cnt, "total_bytes": total, "trigger_counts": trig}, ensure_ascii=False))
if __name__ == "__main__":
    main()
